inline constexpr std::string_view kCommandDefinitionsJSON = R"fly_json([{"id":"spawn-tab","title":"New Blank Tab","desc":"Open a fresh tab using the configured search engine","details":"Creates an isolated Electron webview instance inside the current workspace, initialising with the default search engine whilst respecting your memory configuration.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"spawn-tab","keywords":["tab","open","new","create","blank"]},{"id":"toggle-address","title":"Toggle Floating Address Bar","desc":"Open floating address bar for URL entry and search engine aliases","details":"Displays the modal address bar supporting direct URL routing, query auto-completion, and bang search engine aliases such as !w for Wikipedia.","tip":"Type ! to browse active search aliases or paste raw URLs to navigate instantly.","category":"Tabs & Navigation","actionId":"toggle-address","keywords":["url","address","search","goto","navigate","location"]},{"id":"toggle-dashboard","title":"Toggle Workspace Dashboard","desc":"Full-page tree view of all workspaces, tabs, and windows","details":"Renders an expansive visual hierarchy of every workspace, active tab, and page across the session with bulk management controls.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"toggle-dashboard","keywords":["workspace","tree","tabs","all","overview","dashboard"]},{"id":"toggle-history","title":"Toggle Actionable History","desc":"Search, filter by domain, or purge browsing history records","details":"Opens the searchable history ledger stored locally, featuring domain-level filtering and surgical record purging.","tip":"Filter by specific domains to audit past navigation or clear privacy-sensitive sessions.","category":"Tabs & Navigation","actionId":"toggle-history","keywords":["history","recent","visited","log","purge"]},{"id":"toggle-status-bar","title":"Toggle Status & Mode Bar","desc":"Show or hide the bottom status bar displaying mode, target URL, and TLS state","details":"Toggles the 22px footer status bar across the bottom of the content area. Displays real-time link hover targets, TLS encryption state, active container partition, and modal state.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"toggle-status-bar","keywords":["status","mode","bar","footer","url preview","toggle","bottom"]},{"id":"toggle-clock","title":"Toggle Clock & Date Display","desc":"Show or hide the live clock in the status bar and sidebar","details":"Toggles the real-time clock widget displaying local date and time in the bottom status bar and vertical sidebar.","tip":"Click on the clock at any time to cycle between date and time, time only, and seconds.","category":"Preferences & System","actionId":"toggle-clock","keywords":["clock","time","date","watch","hours","minutes","status"]},{"id":"cycle-clock-format","title":"Cycle Clock Format (Date & Time / Time / Seconds)","desc":"Switch between date and time, compact time, or time with seconds","details":"Rotates the clock presentation mode between standard UK date and time, compact time-only, and high-precision seconds.","tip":"You can also click the clock widget directly in the status bar or sidebar.","category":"Preferences & System","actionId":"cycle-clock-format","keywords":["clock","format","seconds","time","date","cycle","switch"]},{"id":"toggle-window-controls","title":"Toggle Window Controls (Minimise, Maximise, Close)","desc":"Show or hide window action buttons in the sidebar for desktop environments","details":"Displays window management buttons at the top of the vertical sidebar. Ideal for desktop environments such as KDE or GNOME where native window buttons are hidden or disabled.","tip":"Enable this if your desktop environment hides title bars on maximised windows.","category":"Preferences & System","actionId":"toggle-window-controls","keywords":["window","controls","minimize","minimise","maximize","maximise","close","restore","buttons","kde","gnome"]},{"id":"trigger-hints","title":"Toggle Link Hints Overlay","desc":"Display letter tags over clickable links for mouse-free browsing","details":"Injects minimal letter tags over all actionable elements, hyperlinks, and inputs in the viewport to enable rapid keyboard-only navigation.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"trigger-hints","keywords":["hints","click","links","letters","vim","keyboard"]},{"id":"toggle-find","title":"Find In Page","desc":"Search for text matches within the current active webpage","details":"Invokes the in-page search engine across the active webview frame, highlighting all occurrences with instant keyboard cycling.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"toggle-find","keywords":["find","search","page","text","lookup"]},{"id":"reload-active-tab","title":"Reload Active Tab","desc":"Refresh the current webpage document and user assets","details":"Forces the active webview renderer to re-fetch the current URL whilst preserving your workspace tab state and session cache.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"reload-active-tab","keywords":["reload","refresh","page","update"]},{"id":"remove-tab","title":"Close Current Tab","desc":"Tear down active webview and focus the adjacent tab","details":"Safely disposes of the active webview frame, releasing allocated V8 heap memory and re-focusing the nearest remaining tab.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"remove-tab","keywords":["close","remove","delete","tab","exit"]},{"id":"toggle-pin-tab","title":"Pin / Unpin Active Tab","desc":"Pin essential tab to the top of workspace or unpin it","details":"Pinned tabs stay anchored at the top of the tab list, are protected from accidental closure, and are exempted from automatic suspension.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"toggle-pin-tab","keywords":["pin","unpin","sticky","essential","lock","tab"]},{"id":"reset-zoom","title":"Reset Site Zoom Level","desc":"Restore webpage zoom magnification back to 100% default","details":"Restores 100% zoom for this site in every open tab and clears its saved zoom preference.","tip":"Quickly recover standard layout proportions if a page was accidentally zoomed.","category":"Tabs & Navigation","actionId":"reset-zoom","keywords":["zoom","scale","magnify","size","100%"]},{"id":"focus-sidebar","title":"Toggle Sidebar Focus","desc":"Move focus between the sidebar and the active page","details":"Opens the sidebar without focusing a tab or button. Use Tab or the arrow keys to navigate. Run again to return to the page and collapse an unpinned sidebar. A pinned sidebar stays open.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"focus-sidebar","keywords":["sidebar","tabs","focus","list"]},{"id":"focus-nav-buttons","title":"Focus Navigation Buttons","desc":"Cycle focus across Back, Forward, Sidebar, Split, and Menu buttons","details":"Places keyboard focus onto the primary toolbar buttons, allowing navigation using left and right arrow keys.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"focus-nav-buttons","keywords":["buttons","back","forward","top","controls"]},{"id":"focus-webview","title":"Focus Active Webview","desc":"Return keyboard and input focus to the active webpage","details":"Transfers OS input focus directly back into the guest webpage document, allowing uninterrupted typing and interaction.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tabs & Navigation","actionId":"focus-webview","keywords":["focus","webview","page","content"]},{"id":"toggle-sidebar-pin","title":"Toggle Sidebar Expansion (Pin / Unpin)","desc":"Pin sidebar open or auto-shrink to 36px strip expanding on hover","details":"Configures auto-collapse behaviour: when unpinned, the sidebar shrinks to 36px and slides out smoothly when your cursor hovers nearby.","tip":"Unpin for an immersive browsing canvas that leaves controls within easy reach.","category":"Tabs & Navigation","actionId":"toggle-zen-mode","keywords":["pin","lock","unpin","autohide","strip"]},{"id":"toggle-split-vertical","title":"Toggle Dual-Split View (Side-by-Side)","desc":"Tile two webviews side by side in equal columns for multitasking","details":"Splits the active viewport into two concurrent columns, allowing side-by-side comparison, documentation reading, or multitasking.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Split View","actionId":"toggle-split","keywords":["split","dual","side","vertical","columns","multitask"]},{"id":"toggle-split-horizontal","title":"Toggle Dual-Split View (Stacked)","desc":"Tile two webviews stacked vertically in top and bottom rows","details":"Divides the viewport horizontally into stacked top and bottom panes, ideal for viewing reference materials above a web console.","tip":"Useful on vertical monitors or when referencing notes above an active page.","category":"Split View","actionId":"toggle-split-horizontal","keywords":["split","horizontal","stacked","rows","top","bottom"]},{"id":"cycle-split-orientation","title":"Cycle Split View Orientation","desc":"Switch active dual-split layout between side-by-side and stacked","details":"Toggles active multi-pane geometry between side-by-side columns and stacked rows without reloading either webview.","tip":"Adapt your workspace layout on the fly depending on webpage content.","category":"Split View","actionId":"cycle-split-orientation","keywords":["split","rotate","cycle","layout","orientation"]},{"id":"switch-split-focus","title":"Switch Split Pane Focus","desc":"Move active keyboard and scroll focus to the opposite split pane","details":"Switches the active input target between primary and secondary split panes without needing cursor clicks.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Split View","actionId":"switch-split-focus","keywords":["split","focus","pane","switch","alternate"]},{"id":"swap-split-panes","title":"Swap Split Panes","desc":"Exchange positions of the primary and secondary split panes","details":"Reverses the left/right or top/bottom layout ordering of the active dual panes whilst maintaining their states.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Split View","actionId":"swap-split-panes","keywords":["split","swap","flip","reverse","exchange"]},{"id":"close-split-view","title":"Close Split View","desc":"Exit dual-split mode and return to standard single tab viewport","details":"Closes the secondary split pane container and restores the primary webview to the full single viewport.","tip":"Quickly return to single-task focus once your comparison work is finished.","category":"Split View","actionId":"close-split-view","keywords":["split","close","exit","single"]},{"id":"hibernate-tabs","title":"Suspend Inactive Tabs","desc":"Pause eligible background pages without unloading them","details":"Freezes eligible pages in memory, preserving their document and JavaScript state. Busy pages remain running.","tip":"Suspension saves CPU and battery; pages remain in memory.","category":"Performance & Memory","actionId":"hibernate-tabs","keywords":["pause","background","suspend","battery"]},{"id":"wake-all-tabs","title":"Resume Tabs in Workspace","desc":"Resume suspended pages in the active workspace without reloading","details":"Resumes existing pages. Tabs not yet opened since startup remain unloaded.","tip":"Use this when resuming work on a project after an extended idle period.","category":"Performance & Memory","actionId":"wake-all-tabs","keywords":["resume","background","tabs","workspace"]},{"id":"toggle-bookmarks","title":"Bookmarks Manager","desc":"Open your saved bookmarks","details":"Displays your saved bookmarks with filtering and deletion controls.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tools","actionId":"toggle-bookmarks","keywords":["bookmarks","saved","favorites"]},{"id":"add-bookmark","title":"Bookmark Current Page","desc":"Save active webpage title and URL into bookmarks collection","details":"Captures the active tab title and canonical URL, storing it in ~/.config/fly-browser/bookmarks.json for instant recall.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tools","actionId":"add-bookmark","keywords":["bookmark","save","favorite","page","add"]},{"id":"toggle-downloads","title":"Toggle Downloads Shelf","desc":"Slide out bottom downloads drawer with speed and file links","details":"Opens the download shelf showing real-time progress bars, transfer rates, destination paths, and file opening actions.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tools","actionId":"toggle-downloads","keywords":["downloads","files","shelf","drawer"]},{"id":"toggle-devtools","title":"Toggle Active Webview DevTools","desc":"Inspect webpage DOM elements, console logs, and network traffic","details":"Opens Chrome Developer Tools docked or detached for the active webview guest frame to inspect elements and debug scripts.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tools","actionId":"toggle-devtools","keywords":["devtools","inspect","console","debug","elements"]},{"id":"toggle-global-media","title":"Toggle Global Media Playback","desc":"Play or pause audio and video streams across all workspaces","details":"Broadcasts a play/pause toggle signal to media elements across all active webviews, allowing background audio control.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tools","actionId":"toggle-global-media","keywords":["media","play","pause","music","video","stream"]},{"id":"toggle-tab-audio-mute","title":"Toggle Tab Audio Mute","desc":"Mute or unmute audio output for the active tab","details":"Toggles audio mute state for the active tab without pausing video or audio playback.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Tools","actionId":"toggle-tab-audio-mute","keywords":["mute","audio","sound","volume","silence","unmute","speaker"]},{"id":"toggle-global-audio-mute","title":"Toggle Global Audio Mute","desc":"Mute or unmute audio output across all tabs and workspaces","details":"Silences all web audio and media output across all open tabs simultaneously.","tip":"Press M in NORMAL mode to toggle global audio mute.","category":"Tools","actionId":"toggle-global-audio-mute","keywords":["mute","audio","sound","volume","silence","global","all","panictab"]},{"id":"open-scripts-dir","title":"Open User Scripts Directory","desc":"Browse local ~/.config/fly-browser/scripts in file manager","details":"Launches your system file manager in the local user scripts directory where Tampermonkey-compatible scripts reside.","tip":"Drop .user.js files here to automate page behaviours and customise web applications.","category":"User Scripts & Styles","actionId":"open-scripts-dir","keywords":["scripts","userscript","tampermonkey","js","javascript","folder","directory"]},{"id":"open-styles-dir","title":"Open User Styles Directory","desc":"Browse local ~/.config/fly-browser/styles in file manager","details":"Opens the user styles directory in your file manager for injecting custom CSS stylesheets into matched domains.","tip":"Drop .user.css files here to create dark themes or tweak styling for any website.","category":"User Scripts & Styles","actionId":"open-styles-dir","keywords":["styles","userstyle","stylish","css","folder","directory","theme"]},{"id":"open-script-storage-dir","title":"Open User Script Storage Directory","desc":"Browse local ~/.config/fly-browser/script-storage in file manager","details":"Opens the directory containing persistent JSON key-value stores used by GM_setValue and GM_getValue in user scripts.","tip":"Each script stores its isolated state as an individual JSON file here.","category":"User Scripts & Styles","actionId":"open-script-storage-dir","keywords":["storage","gm","userscript","values","database","json","folder","directory"]},{"id":"reload-user-content","title":"Reload User Scripts and Styles","desc":"Hot-reload all custom user scripts and stylesheet injections","details":"Clears the in-memory script cache and re-scans the user directory, hot-reloading scripts and styles across active webviews.","tip":"Run this command immediately after saving CSS or JS changes to preview them live.","category":"User Scripts & Styles","actionId":"reload-user-content","keywords":["reload","refresh","inject","userscripts","userstyles"]},{"id":"toggle-private-mode","title":"Toggle Private Browsing Mode","desc":"Switch session partition to in-memory non-persistent storage","details":"Switches the session state to an isolated in-memory partition where cookies, cache, and history are discarded upon exit.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Preferences & System","actionId":"toggle-private-mode","keywords":["private","incognito","privacy","partition"]},{"id":"test-google-signin","title":"Test Clean Google Sign-In Flow","desc":"Open Google Sign-In in a clean, unauthenticated scratch partition","details":"Purges cached Google auth tokens from the volatile private partition and launches a test tab to verify that Google accepts sign-in without security rejection (rrk=46).","tip":"Use this diagnostic action to audit whether Google authentication works without risking your active workspace logins.","category":"Preferences & System","actionId":"test-google-signin","keywords":["google","auth","signin","login","test","clean","diagnostic","rrk46"]},{"id":"toggle-reader-view","title":"Toggle Reader View on Active Tab","desc":"Distil web article into clean, distraction-free reading layout","details":"Extracts article text, byline, and media using in-engine Mozilla Readability with custom themes and typography.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Web Interaction","actionId":"toggle-reader-view","keywords":["reader","view","read","article","distill","clean","typography","book"]},{"id":"toggle-theme","title":"Toggle Colour Theme (Dark / Light)","desc":"Switch browser interface and webview styling between dark and light","details":"Swaps UI theme variables and inverts webview rendering shaders to match your preferred ambient lighting.","tip":"Quickly adapt screen contrast when working late or in brightly lit environments.","category":"Preferences & System","actionId":"toggle-theme","keywords":["theme","dark","light","mode","colour","color"]},{"id":"toggle-menu-bar","title":"Open Native Settings Menu","desc":"Open the native browser settings menu","details":"Opens the native menu containing browser settings and application controls.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Preferences & System","actionId":"toggle-menu-bar","keywords":["menu","bar","top","native","window"]},{"id":"check-for-updates","title":"Check for Updates","desc":"Check GitHub Releases for newer Fly versions and release notes","details":"Queries the GitHub release ledger to check if a newer Fly version is available, providing direct links to release notes and binary packages.","tip":"Fly tracks upstream Electron and Chromium security releases twice weekly.","category":"Preferences & System","actionId":"check-for-updates","keywords":["update","upgrade","version","release","github","check"]},{"id":"show-whats-new","title":"Show What's New","desc":"Open release highlights for this version in a new tab","details":"Opens the offline release highlights page covering recent features, performance improvements, and security updates.","tip":"Use the binding shown here, or customise this action in Keyboard controls.","category":"Preferences & System","actionId":"show-whats-new","keywords":["whats","new","update","changelog","release","notes","version"]},{"id":"open-diagnostics","title":"Open Diagnostics & Health Hub","desc":"View system health, memory utilisation, logs, and generate sanitised bug reports","details":"Opens the Diagnostics modal overlay displaying Electron runtime versions, GPU acceleration states, process memory breakdown, and volatile in-memory logs.","tip":"Zero telemetry: all diagnostic statistics remain 100% local to your machine.","category":"Preferences & System","actionId":"open-diagnostics","keywords":["diagnostics","diag","health","bug","report","issue","memory","logs","system"]},{"id":"toggle-diagnostics-recording","title":"Toggle Diagnostics Recording (In-Memory)","desc":"Enable or disable local in-memory diagnostic event logging (OFF by default)","details":"Controls the local ring buffer for capturing renderer errors and navigation warnings. Never transmits data across the network.","tip":"Toggle recording on when reproducing issues before generating an issue report.","category":"Preferences & System","actionId":"toggle-diagnostics-recording","keywords":["diagnostics","recording","telemetry","privacy","logs","debug"]}])fly_json";
